CREATE TABLE IF NOT EXISTS inventory_item_aliases (
  id VARCHAR(64) PRIMARY KEY,
  item_id VARCHAR(64) NULL,
  alias_name VARCHAR(160) NOT NULL,
  normalized_alias VARCHAR(160) NOT NULL,
  source_name VARCHAR(80) NOT NULL DEFAULT 'manual',
  status VARCHAR(32) NOT NULL DEFAULT 'pending',
  raw_json JSON NOT NULL,
  created_at VARCHAR(32),
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_inventory_item_alias_source (source_name, normalized_alias),
  INDEX idx_inventory_item_alias_item (item_id),
  INDEX idx_inventory_item_alias_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inventory_unit_conversions (
  id VARCHAR(64) PRIMARY KEY,
  item_id VARCHAR(64) NULL,
  source_unit VARCHAR(32) NOT NULL,
  target_unit VARCHAR(32) NOT NULL,
  factor DECIMAL(18,6) NOT NULL DEFAULT 1,
  status VARCHAR(32) NOT NULL DEFAULT 'active',
  raw_json JSON NOT NULL,
  created_at VARCHAR(32),
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_inventory_unit_conversion (item_id, source_unit, target_unit),
  INDEX idx_inventory_unit_conversion_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inventory_mapping_import_batches (
  id VARCHAR(64) PRIMARY KEY,
  source_name VARCHAR(120) NOT NULL,
  source_file VARCHAR(260),
  total_rows INT NOT NULL DEFAULT 0,
  status VARCHAR(32) NOT NULL DEFAULT 'imported',
  imported_at VARCHAR(32),
  raw_json JSON NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_inventory_mapping_batch_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inventory_mapping_entries (
  id VARCHAR(64) PRIMARY KEY,
  batch_id VARCHAR(64) NOT NULL,
  source_sheet VARCHAR(120) NOT NULL,
  source_row INT NULL,
  department VARCHAR(120) NOT NULL,
  department_id VARCHAR(64) NULL,
  source_scenario VARCHAR(120),
  source_item_name VARCHAR(160) NOT NULL,
  source_usage VARCHAR(500),
  source_note VARCHAR(800),
  rule_type VARCHAR(64) NOT NULL,
  care_type VARCHAR(32),
  trigger_stage VARCHAR(32),
  condition_text VARCHAR(500),
  suggested_quantity DECIMAL(14,2) NULL,
  suggested_unit VARCHAR(32),
  matched_item_id VARCHAR(64) NULL,
  matched_item_name VARCHAR(160) NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'pending',
  import_status VARCHAR(160),
  suggestion VARCHAR(800),
  cannot_publish_reason VARCHAR(800),
  draft_package_id VARCHAR(64) NULL,
  operator_name VARCHAR(120),
  confirmed_at VARCHAR(32),
  raw_json JSON NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_inventory_mapping_source (batch_id, source_sheet, source_row, source_item_name),
  INDEX idx_inventory_mapping_rule_status (rule_type, status),
  INDEX idx_inventory_mapping_department (department_id, department),
  INDEX idx_inventory_mapping_item (matched_item_id),
  INDEX idx_inventory_mapping_draft (draft_package_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @inventory_item_base_unit_sql = (
  SELECT IF(COUNT(*) = 0,
    'ALTER TABLE inventory_items ADD COLUMN base_unit VARCHAR(32) NULL AFTER unit',
    'SELECT 1'
  )
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'inventory_items' AND COLUMN_NAME = 'base_unit'
);
PREPARE stmt FROM @inventory_item_base_unit_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @inventory_item_issue_unit_sql = (
  SELECT IF(COUNT(*) = 0,
    'ALTER TABLE inventory_items ADD COLUMN issue_unit VARCHAR(32) NULL AFTER base_unit',
    'SELECT 1'
  )
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'inventory_items' AND COLUMN_NAME = 'issue_unit'
);
PREPARE stmt FROM @inventory_item_issue_unit_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @inventory_item_precision_sql = (
  SELECT IF(COUNT(*) = 0,
    'ALTER TABLE inventory_items ADD COLUMN quantity_precision INT NOT NULL DEFAULT 2 AFTER issue_unit',
    'SELECT 1'
  )
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'inventory_items' AND COLUMN_NAME = 'quantity_precision'
);
PREPARE stmt FROM @inventory_item_precision_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @inventory_item_normalization_sql = (
  SELECT IF(COUNT(*) = 0,
    'ALTER TABLE inventory_items ADD COLUMN normalization_status VARCHAR(32) NOT NULL DEFAULT ''standard'' AFTER quantity_precision',
    'SELECT 1'
  )
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'inventory_items' AND COLUMN_NAME = 'normalization_status'
);
PREPARE stmt FROM @inventory_item_normalization_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @inventory_item_effective_life_sql = (
  SELECT IF(COUNT(*) = 0,
    'ALTER TABLE inventory_items ADD COLUMN effective_life_managed BOOLEAN NOT NULL DEFAULT FALSE AFTER normalization_status',
    'SELECT 1'
  )
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'inventory_items' AND COLUMN_NAME = 'effective_life_managed'
);
PREPARE stmt FROM @inventory_item_effective_life_sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

